    ll=m.EXAMPLE_LOG_LIK[:,np.array(s)-1].sum(1);out=[]
    for part in [slice(0,NR),slice(NR,None)]:
        l=ll[part];e=logsumexp(l);out+=[e,np.exp(l-e)@m.MEMBERSHIP[part]]
    return out
cache={}
def get(s):
